//! End-to-end checks that a template choice reaches the running server (#602, #607).
//!
//! The model is the **checked-in toy** (`tests/fixtures/toy/toy-qwen2-f32.gguf`,
//! ~113 KB, generated by `scripts/gen_toy_gguf.py`), so the whole file runs in CI;
//! `MINFER_BATCH_TEST_MODEL` overrides it with a real model when one is cached.
//! Two questions are answered here that the unit tests cannot:
//!
//!   1. Does a `--chat-template <FILE>` actually drive a **request** on `serve` and
//!      `viz`? The marker template loads (its refusal only fires for a single
//!      message, which the load-time canary never sends) and refuses at request
//!      time, so a 400 carrying its text proves the file was used; a start without
//!      the override answers the same request 200.
//!   2. Is the no-template notice printed **exactly once, before the listening
//!      banner**, on each path? The toy GGUF carries no `tokenizer.chat_template`, so
//!      it is the artifact; a real model via the env var is converted in place with a
//!      one-byte KV-key rename (same length, so every tensor offset stays valid) — the
//!      helper keeps that path working for someone with a cache but no toy.

use std::io::{BufRead, BufReader, Read, Write};
use std::net::TcpStream;
use std::path::{Path, PathBuf};
use std::process::{Child, Command, Stdio};
use std::sync::mpsc::{self, Receiver};
use std::time::Duration;

/// The notice text asserted below. It is `template::CHATML_NOTICE`, spelled here
/// because an integration test cannot link the binary crate's items.
const CHATML_NOTICE: &str = "using the generic ChatML renderer";

/// A long-lived `minfer serve` / `minfer viz` child with its stderr drained.
struct Server {
    child: Child,
    log: String,
    rx: Receiver<String>,
    port: u16,
    /// The line each mode prints once it is serving: `serve` says "listening on",
    /// `viz` says "viz server on".
    banner: &'static str,
}

impl Server {
    fn spawn(mode: &str, model: &str, port: u16, template: Option<&Path>) -> Server {
        let mut cmd = Command::new(env!("CARGO_BIN_EXE_minfer"));
        cmd.arg(mode)
            .arg(model)
            .args(["--port", &port.to_string(), "--n-ctx", "64"]);
        if let Some(t) = template {
            cmd.arg("--chat-template").arg(t);
        }
        let mut child = cmd
            .stdout(Stdio::piped())
            .stderr(Stdio::piped())
            .spawn()
            .unwrap_or_else(|e| panic!("spawn minfer {mode}: {e}"));
        let stderr = child.stderr.take().expect("stderr pipe");
        let (tx, rx) = mpsc::channel();
        // The banner (and the notice) are on stderr.
        std::thread::spawn(move || {
            for line in BufReader::new(stderr).lines() {
                let Ok(line) = line else { break };
                if tx.send(line).is_err() {
                    break;
                }
            }
        });
        Server {
            child,
            log: String::new(),
            rx,
            port,
            banner: if mode == "serve" {
                "listening on"
            } else {
                "viz server on"
            },
        }
    }

    /// Drain stderr until the listening banner appears; true when it did.
    fn wait_listening(&mut self) -> bool {
        loop {
            match self.rx.recv_timeout(Duration::from_secs(180)) {
                Ok(line) => {
                    let listening = line.contains(self.banner);
                    self.log.push_str(&line);
                    self.log.push('\n');
                    if listening {
                        return true;
                    }
                }
                Err(_) => return false,
            }
        }
    }

    /// One HTTP/1.0 request; returns `(status, body)`.
    fn request(&self, method: &str, path: &str, body: Option<&str>) -> (u16, String) {
        let mut stream = TcpStream::connect(("127.0.0.1", self.port))
            .unwrap_or_else(|e| panic!("connect to {}: {e}", self.port));
        let mut req = format!("{method} {path} HTTP/1.0\r\nHost: localhost\r\n");
        if let Some(b) = body {
            req.push_str(&format!(
                "Content-Type: application/json\r\nContent-Length: {}\r\n",
                b.len()
            ));
        }
        req.push_str("\r\n");
        if let Some(b) = body {
            req.push_str(b);
        }
        stream.write_all(req.as_bytes()).unwrap();
        let mut raw = String::new();
        stream.read_to_string(&mut raw).unwrap();
        let status = raw
            .split_whitespace()
            .nth(1)
            .and_then(|c| c.parse().ok())
            .unwrap_or(0);
        let body = raw.split("\r\n\r\n").nth(1).unwrap_or_default().to_string();
        (status, body)
    }

    fn log(&self) -> &str {
        &self.log
    }
}

impl Drop for Server {
    fn drop(&mut self) {
        let _ = self.child.kill();
        let _ = self.child.wait();
    }
}

/// The checked-in toy model — always present, runs in milliseconds.
fn toy_model() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/toy/toy-qwen2-f32.gguf")
}

/// The model under test: `MINFER_BATCH_TEST_MODEL` when set, else the toy.
fn test_model() -> PathBuf {
    match std::env::var("MINFER_BATCH_TEST_MODEL") {
        Ok(m) => PathBuf::from(m),
        Err(_) => toy_model(),
    }
}

/// The model without a `tokenizer.chat_template`.
///
/// The toy already has none, so this is the toy itself. A real model handed in by
/// the env var is converted once into `/tmp`: renaming the KV key's first byte is a
/// same-length edit (keys are length-prefixed), so the file keeps its size and every
/// tensor offset stays valid, and the loader ignores the unknown key. The assertions
/// are the two properties the trick depends on.
fn model_without_template() -> Option<PathBuf> {
    let src = test_model();
    if !src.exists() {
        return None;
    }
    if src == toy_model() {
        return Some(src);
    }
    let dst = std::env::temp_dir()
        .join("minfer-template-less")
        .join(src.file_name()?);
    if dst.exists() {
        return Some(dst);
    }
    std::fs::create_dir_all(dst.parent()?).ok()?;
    std::fs::copy(&src, &dst).ok()?;
    let before = std::fs::metadata(&dst).ok()?.len();
    let mut data = std::fs::read(&dst).ok()?;
    let needle = b"tokenizer.chat_template";
    let hits: Vec<usize> = data
        .windows(needle.len())
        .enumerate()
        .filter(|(_, w)| *w == needle)
        .map(|(i, _)| i)
        .collect();
    if hits.len() != 1 {
        // A model with no template at all: the copy is already what we need.
        return Some(dst);
    }
    data[hits[0]] = b'X';
    std::fs::write(&dst, &data).ok()?;
    assert_eq!(
        std::fs::metadata(&dst).ok()?.len(),
        before,
        "the rename must not change the file size"
    );
    Some(dst)
}

/// A template that loads (the canary sends 4 and 2 messages) but refuses a
/// one-message request — the shape both the single-turn CLI and `/viz/run` send.
const MARKER_TEMPLATE: &str = "{% if messages|length == 1 %}{{ raise_exception(\"override-marker\") }}{% endif %}U:{{ messages[0][\"content\"] }}";

/// The marker template in its own file.
///
/// `name` must be unique per test: the tests run in parallel threads, and a shared
/// path means one test's `File::create` truncates the file another is reading —
/// which surfaced as "the template file is empty" (#611's first CI run passed, the
/// full suite raced).
fn marker_file(name: &str) -> PathBuf {
    template_file(name, MARKER_TEMPLATE)
}

/// Any template in its own file (`name` unique per test, same reason as above).
fn template_file(name: &str, text: &str) -> PathBuf {
    let dir = std::env::temp_dir().join("minfer-template-e2e");
    std::fs::create_dir_all(&dir).expect("scratch dir");
    let path = dir.join(name);
    std::fs::write(&path, text).expect("write template");
    path
}

/// A template with no `tools` branch at all: whatever the request sends cannot
/// reach the prompt (#597).
const NO_TOOLS_BRANCH_TEMPLATE: &str = "U:{{ messages[0][\"content\"] }}";

/// A template that does render `tools`, so a request carrying them is served.
const TOOLS_BRANCH_TEMPLATE: &str =
    "{% if tools %}T:{{ tools|length }}|{% endif %}U:{{ messages[0][\"content\"] }}";

#[test]
fn serve_starts_and_answers_health_with_an_override_file() {
    let model = test_model();
    let template = marker_file("serve-health.jinja");
    // The marker only fires on a one-message request; a plain /health never renders.
    let mut server = Server::spawn("serve", &model.to_string_lossy(), 18099, Some(&template));
    assert!(
        server.wait_listening(),
        "the server never printed its banner; log so far:\n{}",
        server.log()
    );
    let (status, body) = server.request("GET", "/health", None);
    assert_eq!(status, 200, "health status; body:\n{body}");
    assert!(body.contains("\"status\":\"ok\""), "health body:\n{body}");
}

#[test]
fn serve_renders_from_the_override_at_request_time() {
    let model = test_model();
    let template = marker_file("serve-request.jinja");
    let body = r#"{"model":"m","messages":[{"role":"user","content":"hi"}],"max_tokens":1}"#;

    let mut with = Server::spawn("serve", &model.to_string_lossy(), 18100, Some(&template));
    assert!(
        with.wait_listening(),
        "no banner; log so far:\n{}",
        with.log()
    );
    let (status, response) = with.request("POST", "/v1/chat/completions", Some(body));
    assert_eq!(
        status, 400,
        "the override's refusal must surface as 400; body:\n{response}"
    );
    assert!(
        response.contains("override-marker"),
        "the override template's own text must be in the error; body:\n{response}"
    );

    // Control: the same request against the GGUF's own template is not refused, so
    // the 400 above is the file's doing and not the artifact's.
    let mut without = Server::spawn("serve", &model.to_string_lossy(), 18101, None);
    assert!(
        without.wait_listening(),
        "no banner; log so far:\n{}",
        without.log()
    );
    let (status, response) = without.request("POST", "/v1/chat/completions", Some(body));
    assert_eq!(
        status, 200,
        "without the override the request must render; body:\n{response}"
    );
    assert!(!response.contains("override-marker"), "{response}");
}

#[test]
fn viz_renders_from_the_override_at_request_time() {
    let model = test_model();
    let template = marker_file("viz-request.jinja");
    let body = r#"{"prompt":"hi","max_tokens":1}"#;

    let mut with = Server::spawn("viz", &model.to_string_lossy(), 18102, Some(&template));
    assert!(
        with.wait_listening(),
        "no banner; log so far:\n{}",
        with.log()
    );
    let (status, response) = with.request("POST", "/viz/run", Some(body));
    assert_eq!(
        status, 400,
        "the override's refusal must surface as 400; body:\n{response}"
    );
    assert!(
        response.contains("override-marker"),
        "the override template's own text must be in the error; body:\n{response}"
    );

    let mut without = Server::spawn("viz", &model.to_string_lossy(), 18103, None);
    assert!(
        without.wait_listening(),
        "no banner; log so far:\n{}",
        without.log()
    );
    let (status, response) = without.request("POST", "/viz/run", Some(body));
    assert_eq!(
        status, 200,
        "without the override the request must render; body:\n{response}"
    );
    assert!(!response.contains("override-marker"), "{response}");
}

#[test]
fn the_chatml_notice_is_printed_once_before_the_banner_on_serve_and_viz() {
    let Some(model) = model_without_template() else {
        eprintln!("skipped: MINFER_BATCH_TEST_MODEL does not exist");
        return;
    };
    for (mode, port) in [("serve", 18104u16), ("viz", 18105)] {
        let mut server = Server::spawn(mode, &model.to_string_lossy(), port, None);
        assert!(
            server.wait_listening(),
            "{mode}: no banner; log so far:\n{}",
            server.log()
        );
        let log = server.log();
        let lines: Vec<&str> = log.lines().collect();
        let notices: Vec<usize> = lines
            .iter()
            .enumerate()
            .filter(|(_, l)| l.contains(CHATML_NOTICE))
            .map(|(i, _)| i)
            .collect();
        let banner = lines
            .iter()
            .position(|l| l.contains(server.banner))
            .expect("the banner was seen");
        assert_eq!(
            notices.len(),
            1,
            "{mode}: the notice must be printed exactly once; log:\n{log}"
        );
        assert!(
            notices[0] < banner,
            "{mode}: the notice must precede the banner; log:\n{log}"
        );
    }
}

/// `--cnv` shares `startup_template` with `serve`/`viz`, so the printed-once
/// property is the only part not covered. No stdin session is involved:
/// `-st` ends the loop after the first turn, so a closed stdin is enough —
/// and passing one keeps the test from depending on an interactive terminal.
#[test]
fn conversation_announces_chatml_once_without_reading_stdin() {
    let Some(model) = model_without_template() else {
        eprintln!("skipped: MINFER_BATCH_TEST_MODEL does not exist");
        return;
    };
    let out = Command::new(env!("CARGO_BIN_EXE_minfer"))
        .args(["--cnv", "-st", "-n", "1"])
        .arg(&model)
        .arg("hi")
        .stdin(Stdio::null())
        .output()
        .expect("spawn minfer --cnv -st");
    let stderr = String::from_utf8_lossy(&out.stderr).to_string();
    assert_eq!(
        out.status.code(),
        Some(0),
        "one turn must succeed; stderr:\n{stderr}"
    );
    assert_eq!(
        stderr.matches(CHATML_NOTICE).count(),
        1,
        "the notice must be printed exactly once; stderr:\n{stderr}"
    );
    assert!(!stderr.contains("panicked"), "{stderr}");
}

/// #597: the request field reaches the renderer, and what the renderer does with
/// it is visible over HTTP.
///
/// Three states, one server run each: a template without a `tools` branch is a
/// 400 that names the missing branch (never a silently tools-free prompt) while
/// the same request without tools is a 200; a template *with* a branch serves the
/// request; and a `tool_choice` mode that needs output extraction is the
/// handler's own 400. The prompt bytes themselves are gated in
/// `src/template/tests/tools.rs` against the transformers reference — a toy model
/// cannot show them here.
#[test]
fn serve_refuses_tools_a_template_cannot_render_and_serves_the_ones_it_can() {
    let model = test_model();
    let tools = r#","tools":[{"type":"function","function":{"name":"get_weather"}}]"#;
    let with_tools =
        format!(r#"{{"messages":[{{"role":"user","content":"hi"}}],"max_tokens":1{tools}}}"#);
    let without_tools = r#"{"messages":[{"role":"user","content":"hi"}],"max_tokens":1}"#;

    // (a) no tools branch: refused by name, and the same request without tools
    //     still works — the 400 is about the definitions, not the template.
    let plain = template_file("tools-none.jinja", NO_TOOLS_BRANCH_TEMPLATE);
    let mut server = Server::spawn("serve", &model.to_string_lossy(), 18106, Some(&plain));
    assert!(
        server.wait_listening(),
        "no banner; log so far:\n{}",
        server.log()
    );
    let (status, response) = server.request("POST", "/v1/chat/completions", Some(&with_tools));
    assert_eq!(
        status, 400,
        "tools against a template with no tools branch must be 400; body:\n{response}"
    );
    assert!(
        response.contains("no `tools` branch"),
        "the refusal must name the missing branch; body:\n{response}"
    );
    let (status, response) = server.request("POST", "/v1/chat/completions", Some(without_tools));
    assert_eq!(
        status, 200,
        "the same request without tools must render; body:\n{response}"
    );

    // (b) a template that renders tools serves the request.
    let branch = template_file("tools-branch.jinja", TOOLS_BRANCH_TEMPLATE);
    let mut server = Server::spawn("serve", &model.to_string_lossy(), 18107, Some(&branch));
    assert!(
        server.wait_listening(),
        "no banner; log so far:\n{}",
        server.log()
    );
    let (status, response) = server.request("POST", "/v1/chat/completions", Some(&with_tools));
    assert_eq!(
        status, 200,
        "a template with a tools branch must serve the request; body:\n{response}"
    );
    assert!(
        response.contains("\"content\""),
        "a completion shape is expected; body:\n{response}"
    );

    // (c) `tool_choice: "required"` is refused before the render: it needs the
    //     model's output to be parsed, which this server does not do.
    let required = format!(
        r#"{{"messages":[{{"role":"user","content":"hi"}}],"max_tokens":1{tools},"tool_choice":"required"}}"#
    );
    let (status, response) = server.request("POST", "/v1/chat/completions", Some(&required));
    assert_eq!(
        status, 400,
        "tool_choice \"required\" must be refused; body:\n{response}"
    );
    assert!(
        response.contains("extracted from the model's output"),
        "the refusal must name what is missing; body:\n{response}"
    );
}
